import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Gender {
  MALE = 'Male',
  FEMALE = 'Female',
  OTHER = 'Other'
}

export enum Goal {
  STEADY = 'Steady Weight',
  INCREASE = 'Weight Gain',
  DECREASE = 'Weight Loss'
}

export interface UserProfile {
  name: string;
  weight: number; // in kg
  height: number; // in cm
  gender: Gender;
  goal: Goal;
  waist?: number;
  hips?: number;
  chest?: number;
  dailyCalorieTarget: number;
  macros: {
    protein: number;
    carbs: number;
    fat: number;
  };
}

export interface Meal {
  id: string;
  type: string; // Breakfast, Lunch, Dinner, Snack, etc.
  name: string;
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
  description: string;
  image?: string;
  timestamp: number;
}

export interface DailyLog {
  date: string; // YYYY-MM-DD
  meals: Meal[];
}

import { GoogleGenAI, Type } from "@google/genai";
import { UserProfile, Gender, Goal } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const calculatePersonalizedGoals = async (profile: Partial<UserProfile>): Promise<{ targetCalories: number, macros: { protein: number, carbs: number, fat: number } }> => {
  const prompt = `
    Based on the following user data:
    Name: ${profile.name}
    Weight: ${profile.weight}kg
    Height: ${profile.height}cm
    Gender: ${profile.gender}
    Goal: ${profile.goal}

    Optional measurements: 
    Waist: ${profile.waist}cm, Hips: ${profile.hips}cm, Chest: ${profile.chest}cm

    Calculate the recommended daily calorie intake and macro nutrients (Protein, Carbs, Fat in grams).
    Return the result in JSON format.
  `;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          targetCalories: { type: Type.NUMBER },
          macros: {
            type: Type.OBJECT,
            properties: {
              protein: { type: Type.NUMBER },
              carbs: { type: Type.NUMBER },
              fat: { type: Type.NUMBER }
            },
            required: ['protein', 'carbs', 'fat']
          }
        },
        required: ['targetCalories', 'macros']
      }
    }
  });

  return JSON.parse(response.text);
};

export const estimateMealCalories = async (
  mealDescription: string,
  base64Image?: string
): Promise<{ name: string, calories: number, protein: number, carbs: number, fat: number }> => {
  const parts: any[] = [{ text: `Estimate the calories and macros (protein, carbs, fat in grams) for this meal: "${mealDescription}". If an image is provided, use it to increase accuracy. Return JSON format.` }];

  if (base64Image) {
    parts.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: base64Image.split(',')[1] // remove data:image/jpeg;base64,
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          calories: { type: Type.NUMBER },
          protein: { type: Type.NUMBER },
          carbs: { type: Type.NUMBER },
          fat: { type: Type.NUMBER }
        },
        required: ['name', 'calories', 'protein', 'carbs', 'fat']
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserProfile, Meal, Gender, Goal, DailyLog } from './types';
import { calculatePersonalizedGoals } from './services/geminiService';
import Onboarding from './components/Onboarding';
import Dashboard from './components/Dashboard';
import { Plus, Camera, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [loading, setLoading] = useState(true);
  const [isInitializing, setIsInitializing] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('nutrilens_user');
    const savedMeals = localStorage.getItem('nutrilens_meals');

    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    if (savedMeals) {
      setMeals(JSON.parse(savedMeals));
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nutrilens_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrilens_meals', JSON.stringify(meals));
  }, [meals]);

  const handleOnboardingComplete = async (profile: Partial<UserProfile>) => {
    setIsInitializing(true);
    try {
      const results = await calculatePersonalizedGoals(profile);
      const fullProfile: UserProfile = {
        name: profile.name!,
        weight: profile.weight!,
        height: profile.height!,
        gender: profile.gender!,
        goal: profile.goal!,
        waist: profile.waist,
        hips: profile.hips,
        chest: profile.chest,
        dailyCalorieTarget: results.targetCalories,
        macros: results.macros,
      };
      setUser(fullProfile);
    } catch (error) {
      console.error("Error calculating goals:", error);
      alert("Failed to calculate goals. Please try again.");
    } finally {
      setIsInitializing(false);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
  };

  const handleReset = () => {
    if (confirm("Reset everything? This will delete all logs.")) {
      localStorage.removeItem('nutrilens_user');
      localStorage.removeItem('nutrilens_meals');
      setUser(null);
      setMeals([]);
    }
  };

  if (loading || isInitializing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <Loader2 className="w-12 h-12 text-blue-500 animate-spin mb-4" />
        <h2 className="text-xl font-semibold text-slate-800">
          {isInitializing ? "Crafting your personalized nutrition plan..." : "Loading NutriLens..."}
        </h2>
        <p className="text-slate-500 mt-2">Setting up your journey to a healthier you.</p>
      </div>
    );
  }

  if (!user) {
    return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-20 max-w-md mx-auto relative shadow-2xl overflow-hidden flex flex-col">
      <Dashboard 
        user={user} 
        meals={meals} 
        onAddMeal={handleAddMeal} 
        onReset={handleReset} 
      />
    </div>
  );
};

export default App;

