import React, { useState } from 'react';
import { UserProfile, Meal } from '../types';
import { Plus, Settings, Calendar, Camera, Utensils, Zap, Flame, Info, Check, AlertTriangle, AlertCircle, Trash2 } from 'lucide-react';
import MealEntryModal from './MealEntryModal';

interface Props {
  user: UserProfile;
  meals: Meal[];
  onAddMeal: (meal: Meal) => void;
  onReset: () => void;
}

const Dashboard: React.FC<Props> = ({ user, meals, onAddMeal, onReset }) => {
  const [showEntryModal, setShowEntryModal] = useState(false);
  const [selectedMealType, setSelectedMealType] = useState<string>('Lunch');

  const todayStr = new Date().toISOString().split('T')[0];
  const todayMeals = meals.filter(m => new Date(m.timestamp).toISOString().split('T')[0] === todayStr);

  const totalConsumed = todayMeals.reduce((acc, m) => acc + m.calories, 0);
  const totalProtein = todayMeals.reduce((acc, m) => acc + m.protein, 0);
  const totalCarbs = todayMeals.reduce((acc, m) => acc + m.carbs, 0);
  const totalFat = todayMeals.reduce((acc, m) => acc + m.fat, 0);

  const calorieDiff = Math.abs(totalConsumed - user.dailyCalorieTarget);

  let statusColor = 'text-green-500';
  let bgColor = 'bg-green-500';
  let statusIcon = <Check className="w-5 h-5" />;
  let statusText = "On Track";

  if (calorieDiff >= 500) {
    statusColor = 'text-red-500';
    bgColor = 'bg-red-500';
    statusIcon = <AlertCircle className="w-5 h-5" />;
    statusText = totalConsumed > user.dailyCalorieTarget ? "Way Over" : "Way Under";
  } else if (calorieDiff >= 200) {
    statusColor = 'text-amber-500';
    bgColor = 'bg-amber-500';
    statusIcon = <AlertTriangle className="w-5 h-5" />;
    statusText = "Near Limit";
  }

  const openAddMeal = (type: string) => {
    setSelectedMealType(type);
    setShowEntryModal(true);
  };

  return (
    <div className="flex-1 flex flex-col h-full overflow-y-auto">
      {/* Header */}
      <div className="p-6 bg-white sticky top-0 z-10 border-b border-slate-100 ios-glass">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-slate-400 text-sm font-medium">Hello, {user.name} 👋</h2>
            <h1 className="text-2xl font-bold text-slate-900">Today's Nutrition</h1>
          </div>
          <button onClick={onReset} className="p-2 bg-slate-100 rounded-full text-slate-400 hover:text-red-500 transition-colors">
            <Trash2 className="w-5 h-5" />
          </button>
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Goal Card */}
        <div className="bg-white rounded-[32px] p-6 shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-6">
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-xl bg-slate-100 ${statusColor}`}>
                {statusIcon}
              </div>
              <div>
                <h3 className="font-bold text-slate-900">{statusText}</h3>
                <p className="text-xs text-slate-400">Goal: {user.goal}</p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider">Target</p>
              <p className="text-xl font-bold text-green-600">{user.dailyCalorieTarget} <span className="text-xs text-slate-400 font-medium">kcal</span></p>
