              <p className="font-bold text-slate-900">{totalCarbs}g <span className="text-[10px] text-slate-400">/ {user.macros.carbs}g</span></p>
              <div className="h-1 bg-slate-100 rounded-full mt-1">
                <div className="h-full bg-amber-400 rounded-full" style={{ width: `${Math.min((totalCarbs/user.macros.carbs)*100, 100)}%` }} />
              </div>
            </div>
            <div className="text-center">
              <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">Fat</p>
