                      <div className="w-10 h-10 rounded-2xl bg-slate-50 flex items-center justify-center">
                        <Utensils className="w-5 h-5 text-slate-400" />
                      </div>
                      <span className="font-bold text-slate-800">{type}</span>
                    </div>
                    {mealForType.length === 0 ? (
