import React, { useState, useRef } from 'react';
import { Camera, X, Upload, Loader2, Sparkles, Send } from 'lucide-react';
import { estimateMealCalories } from '../services/geminiService';
import { Meal } from '../types';

interface Props {
  type: string;
  onClose: () => void;
  onAdd: (meal: Meal) => void;
}

const MealEntryModal: React.FC<Props> = ({ type, onClose, onAdd }) => {
  const [description, setDescription] = useState('');
  const [image, setImage] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!description && !image) return;

    setIsAnalyzing(true);
    try {
      const result = await estimateMealCalories(description || "Meal in photo", image || undefined);

      const newMeal: Meal = {
        id: Math.random().toString(36).substr(2, 9),
        type,
        name: result.name,
        calories: result.calories,
        protein: result.protein,
        carbs: result.carbs,
        fat: result.fat,
        description: description,
        image: image || undefined,
        timestamp: Date.now(),
      };

      onAdd(newMeal);
      onClose();
    } catch (error) {
      console.error("Analysis error:", error);
      alert("AI Analysis failed. Please check your connection and try again.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/40 backdrop-blur-sm p-0 sm:items-center sm:p-4">
      <div className="w-full max-w-md bg-white rounded-t-[40px] sm:rounded-[40px] shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="p-8">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-slate-900">Add {type}</h2>
            <button onClick={onClose} className="p-2 bg-slate-100 rounded-full text-slate-400">
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="space-y-6">
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="w-full aspect-square max-h-64 rounded-[32px] border-2 border-dashed border-slate-200 bg-slate-50 flex flex-col items-center justify-center cursor-pointer overflow-hidden relative group"
            >
              {image ? (
                <>
                  <img src={image} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                    <Camera className="w-10 h-10 text-white" />
                  </div>
                </>
              ) : (
                <>
                  <div className="p-4 bg-white rounded-2xl shadow-sm mb-3">
                    <Camera className="w-8 h-8 text-blue-500" />
                  </div>
                  <p className="text-sm font-bold text-slate-400">Tap to snap or upload</p>
                </>
              )}
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImageChange} 
                className="hidden" 
                accept="image/*" 
              />
            </div>

            <div>
              <label className="text-sm font-bold text-slate-700 mb-2 block">Describe what you ate</label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Example: 2 scrambled eggs and a piece of whole grain toast..."
                className="w-full p-4 bg-slate-50 border-none rounded-2xl min-h-[100px] focus:ring-2 focus:ring-blue-500 text-slate-700 transition-all resize-none"
              />
            </div>

            <button
              onClick={handleAnalyze}
              disabled={(!description && !image) || isAnalyzing}
              className={`w-full py-4 rounded-2xl flex items-center justify-center gap-2 font-bold transition-all shadow-xl ${
                isAnalyzing 
                  ? 'bg-slate-100 text-slate-400' 
                  : 'bg-blue-600 text-white shadow-blue-200 active:scale-95'
              }`}
            >
              {isAnalyzing ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  AI is analyzing...
                </>
              ) : (
                <>
                  <Sparkles className="w-5 h-5" />
                  Analyze with AI
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MealEntryModal;

import React, { useState, useEffect } from 'react';
import { UserProfile, Meal } from './types';
import { calculatePersonalizedGoals } from './services/geminiService';
import Onboarding from './components/Onboarding';
import Dashboard from './components/Dashboard';
import ProfileSettings from './components/ProfileSettings';
import { Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [meals, setMeals] = useState<Meal[]>([]);
  const [loading, setLoading] = useState(true);
  const [isInitializing, setIsInitializing] = useState(false);
  const [showProfile, setShowProfile] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('nutrilens_user');
    const savedMeals = localStorage.getItem('nutrilens_meals');

    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    if (savedMeals) {
      setMeals(JSON.parse(savedMeals));
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (user) {
      localStorage.setItem('nutrilens_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    localStorage.setItem('nutrilens_meals', JSON.stringify(meals));
  }, [meals]);

  const handleOnboardingComplete = async (profile: Partial<UserProfile>) => {
    setIsInitializing(true);
    try {
      const results = await calculatePersonalizedGoals(profile);
      const fullProfile: UserProfile = {
        name: profile.name!,
        weight: profile.weight!,
        height: profile.height!,
        gender: profile.gender!,
        goal: profile.goal!,
        waist: profile.waist,
        hips: profile.hips,
        chest: profile.chest,
        dailyCalorieTarget: results.targetCalories,
        macros: results.macros,
      };
      setUser(fullProfile);
      setShowProfile(false);
    } catch (error) {
      console.error("Error calculating goals:", error);
      alert("Failed to calculate goals. Please try again.");
    } finally {
      setIsInitializing(false);
    }
  };

  const handleAddMeal = (meal: Meal) => {
    setMeals(prev => [meal, ...prev]);
  };

  const handleUpdateMeal = (updatedMeal: Meal) => {
    setMeals(prev => prev.map(m => m.id === updatedMeal.id ? updatedMeal : m));
  };

  const handleDeleteMeal = (id: string) => {
    setMeals(prev => prev.filter(m => m.id !== id));
  };

  const handleReset = () => {
    if (confirm("Reset everything? This will delete all logs.")) {
      localStorage.removeItem('nutrilens_user');
      localStorage.removeItem('nutrilens_meals');
      setUser(null);
      setMeals([]);
      setShowProfile(false);
    }
  };

  if (loading || isInitializing) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-6 text-center">
        <Loader2 className="w-12 h-12 text-blue-500 animate-spin mb-4" />
        <h2 className="text-xl font-semibold text-slate-800">
          {isInitializing ? "Recalculating your plan..." : "Loading NutriLens..."}
        </h2>
        <p className="text-slate-500 mt-2">Personalizing your experience.</p>
      </div>
    );
  }

  if (!user) {
    return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto relative shadow-2xl overflow-hidden flex flex-col">
      {showProfile ? (
        <ProfileSettings 
          user={user} 
          onSave={handleOnboardingComplete} 
          onBack={() => setShowProfile(false)} 
          onReset={handleReset}
        />
      ) : (
        <Dashboard 
          user={user} 
          meals={meals} 
          onAddMeal={handleAddMeal} 
          onUpdateMeal={handleUpdateMeal}
          onDeleteMeal={handleDeleteMeal}
          onOpenProfile={() => setShowProfile(true)}
        />
      )}
    </div>
  );
};

export default App;

